package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException; import com.starlight.greetings.domain.moderation.ContentModerator; import java.nio.charset.StandardCharsets; import java.text.Normalizer; import java.security.MessageDigest; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JdbcLetterWriteService implements LetterWriteService { private final JdbcTemplate jdbc; private final ContentModerator moderator; public JdbcLetterWriteService(JdbcTemplate jdbc, ContentModerator moderator){this.jdbc=jdbc;this.moderator=moderator;}
 @Transactional public String write(Map<String,Object> input){String bridge=(String)input.get("bridgeId"),question=(String)input.get("questionId"),body=(String)input.get("body"),user=(String)input.get("userId"),nickname=(String)input.get("nickname"),key=(String)input.get("idempotencyKey");int theme=input.get("theme") instanceof Number n?n.intValue():0;if(body==null||body.trim().isEmpty()||body.codePointCount(0,body.length())>150)throw bad("INVALID_BODY","편지 내용을 1~150자로 입력해 주세요.");String baseCategory=moderator.category(body);if(baseCategory!=null)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"CONTENT_REVISE","편지 내용을 수정해 주세요.");if(key==null||key.length()<8||key.length()>100)throw bad("IDEMPOTENCY_KEY_REQUIRED","제출 요청 키를 확인해 주세요.");if(theme<1||theme>4)throw bad("INVALID_THEME","유리병 테마를 다시 선택해 주세요.");Boolean exists=jdbc.queryForObject("select exists(select 1 from bridges where id=? and active=true)",Boolean.class,bridge);if(!Boolean.TRUE.equals(exists))throw new ApiException(HttpStatus.NOT_FOUND,"BRIDGE_NOT_FOUND","다리를 찾을 수 없습니다.");String searchable=Normalizer.normalize(body, Normalizer.Form.NFKC).toLowerCase(Locale.KOREAN);for(String phrase:jdbc.query("select phrase from moderation_rules where active=true",(r,i)->r.getString(1)))if(searchable.contains(Normalizer.normalize(phrase, Normalizer.Form.NFKC).toLowerCase(Locale.KOREAN)))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"CONTENT_REVISE","편지 내용을 수정해 주세요.");String hash=digest(bridge+"\n"+question+"\n"+body+"\n"+theme);jdbc.update("insert into request_keys (user_id,key,request_hash) values (?::uuid,?,?) on conflict do nothing",user,key,hash);var keys=jdbc.query("select request_hash,letter_id::text from request_keys where user_id=?::uuid and key=? for update",(r,i)->new String[]{r.getString(1),r.getString(2)},user,key);if(!keys.get(0)[0].equals(hash))throw new ApiException(HttpStatus.CONFLICT,"IDEMPOTENCY_CONFLICT","같은 요청 키로 다른 편지를 제출할 수 없습니다.");if(keys.get(0)[1]!=null)return keys.get(0)[1];var questions=jdbc.query("select id::text from questions where bridge_id=? and status='published' and effective_at<=now() order by effective_at desc,id desc limit 1",(r,i)->r.getString(1),bridge);if(questions.isEmpty()||!questions.get(0).equals(question))throw new ApiException(HttpStatus.CONFLICT,"QUESTION_CHANGED","질문이 바뀌었어요. 새 질문을 확인해 주세요.");String id=UUID.randomUUID().toString();jdbc.update("insert into letters (id,bridge_id,question_id,author_user_id,display_nickname,body,theme,is_seed,status) values (?::uuid,?,?::uuid,?::uuid,?,?,?,false,'published')",id,bridge,question,user,nickname,body.trim(),theme);jdbc.update("update request_keys set letter_id=?::uuid where user_id=?::uuid and key=?",id,user,key);return id;}
 private ApiException bad(String c,String m){return new ApiException(HttpStatus.BAD_REQUEST,c,m);}private String digest(String v){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
